using System;
using System.Buffers.Binary;
using System.Collections.Generic;

// 프레임 = [길이 uint16 리틀 엔디언][payload 길이만큼]. payload 는 0 ~ MaxPayload 바이트.
// 연결(소켓) 하나당 MessageFramer 인스턴스 하나를 쓴다.
public sealed class MessageFramer
{
    public const int HeaderSize = 2;
    public const int MaxPayload = 1024;

    private bool _broken;

    // Receive 가 돌려준 바이트 덩어리를 그대로 넘긴다.
    // 완성된 메시지의 payload 를 도착 순서대로 output 에 추가한다.
    // 길이가 MaxPayload 를 넘는 프레임을 만나면 false 를 반환하고, 그 뒤의 Feed 는 항상 false 다.
    public bool Feed(ReadOnlySpan<byte> chunk, List<byte[]> output)
    {
        if (_broken) return false;
        if (chunk.Length < HeaderSize) return true;

        int len = BinaryPrimitives.ReadUInt16LittleEndian(chunk);
        if (len >= MaxPayload)
        {
            _broken = true;
            return false;
        }

        if (chunk.Length < HeaderSize + len) return true;

        output.Add(chunk.Slice(HeaderSize, len).ToArray());
        return true;
    }
}

