    static byte[] Txt(string s) { return System.Text.Encoding.ASCII.GetBytes(s); }

    static byte[] Pattern(int n, int salt)
    {
        byte[] b = new byte[n];
        for (int i = 0; i < n; i++) b[i] = (byte)(i * 7 + salt);
        return b;
    }

    // 메시지들을 [len lo][len hi][payload] 로 이어 붙인 바이트 스트림
    static byte[] Stream(System.Collections.Generic.List<byte[]> msgs)
    {
        var s = new System.Collections.Generic.List<byte>();
        foreach (byte[] m in msgs) { s.Add((byte)(m.Length & 0xFF)); s.Add((byte)(m.Length >> 8)); s.AddRange(m); }
        return s.ToArray();
    }

    static System.Collections.Generic.List<byte[]> L(params byte[][] m) { return new System.Collections.Generic.List<byte[]>(m); }

    static string Show(byte[] m)
    {
        return m.Length <= 12 ? "[" + System.Convert.ToHexString(m) + "]" : "[" + m.Length + "바이트]";
    }

    static string Diff(System.Collections.Generic.List<byte[]> got, System.Collections.Generic.List<byte[]> want)
    {
        for (int i = 0; i < want.Count && i < got.Count; i++)
        {
            if (got[i] == null) return i + "번째 메시지가 null";
            if (!System.MemoryExtensions.SequenceEqual<byte>(got[i], want[i])) return i + "번째 메시지 기대 " + Show(want[i]) + " / 결과 " + Show(got[i]);
        }
        return got.Count == want.Count ? null : "메시지 수 기대 " + want.Count + " / 결과 " + got.Count;
    }

    // stream 을 cuts 위치에서 잘라 순서대로 Feed 한다. cuts 는 오름차순.
    static string FeedCuts(byte[] stream, int[] cuts, System.Collections.Generic.List<byte[]> want)
    {
        var f = new MessageFramer();
        var got = new System.Collections.Generic.List<byte[]>();
        int from = 0;
        for (int k = 0; k <= cuts.Length; k++)
        {
            int to = k < cuts.Length ? cuts[k] : stream.Length;
            if (!f.Feed(new System.ReadOnlySpan<byte>(stream, from, to - from), got))
                return "정상 스트림인데 Feed 가 false (자른 위치 " + string.Join(",", cuts) + ")";
            from = to;
        }
        string d = Diff(got, want);
        return d == null ? null : d + " (총 " + stream.Length + "바이트, 자른 위치 " + (cuts.Length == 0 ? "없음" : string.Join(",", cuts)) + ")";
    }

    public static void Main()
    {
        var seq = L(Txt("MOVE 3 4"), new byte[0], Pattern(300, 1), Txt("ATK"));
        byte[] seqStream = Stream(seq);

        Run("one-message-per-chunk", () =>
        {
            var f = new MessageFramer();
            var got = new System.Collections.Generic.List<byte[]>();
            foreach (byte[] m in L(Txt("HELLO"), Txt("MOVE 3 4"), Pattern(300, 5)))
                if (!f.Feed(Stream(L(m)), got)) return "Feed 가 false";
            if (!f.Feed(System.ReadOnlySpan<byte>.Empty, got)) return "빈 chunk 에 Feed 가 false";
            return Diff(got, L(Txt("HELLO"), Txt("MOVE 3 4"), Pattern(300, 5)));
        });

        Run("many-messages-one-chunk", () =>
            FeedCuts(Stream(L(Txt("A"), Txt("B"))), new int[0], L(Txt("A"), Txt("B")))
            ?? FeedCuts(seqStream, new int[0], seq));

        Run("split-at-every-boundary", () =>
        {
            string e = FeedCuts(new byte[] { 3, 0, 0x41, 0x42, 0x43 }, new[] { 3 }, L(Txt("ABC")));
            if (e != null) return e;
            for (int cut = 1; cut < seqStream.Length; cut++)
            {
                e = FeedCuts(seqStream, new[] { cut }, seq);
                if (e != null) return e;
            }
            return null;
        });

        Run("byte-by-byte", () =>
        {
            var f = new MessageFramer();
            var got = new System.Collections.Generic.List<byte[]>();
            for (int i = 0; i < seqStream.Length; i++)
                if (!f.Feed(new System.ReadOnlySpan<byte>(seqStream, i, 1), got)) return "Feed 가 false (" + i + "번째 바이트)";
            return Diff(got, seq);
        });

        Run("split-three-ways", () =>
        {
            var small = L(Txt("HI"), new byte[0], Txt("SKILL 7"), Txt("X"));
            byte[] s = Stream(small);
            for (int i = 1; i < s.Length; i++)
                for (int j = i + 1; j < s.Length; j++)
                {
                    string e = FeedCuts(s, new[] { i, j }, small);
                    if (e != null) return e;
                }
            return null;
        });

        Run("empty-and-max-payload", () =>
        {
            var msgs = L(new byte[0], Pattern(1024, 3), new byte[0], new byte[0], Pattern(1023, 9));
            byte[] s = Stream(msgs);
            return FeedCuts(s, new int[0], msgs) ?? FeedCuts(s, new[] { 1, 3, 500, 1027, 1029, 1031 }, msgs);
        });

        Run("oversize-length-rejected", () =>
        {
            byte[] bad = { 2, 0, 0x4F, 0x4B, 0x01, 0x04, 0x99 };   // "OK" 다음에 길이 1025 헤더
            for (int cut = 0; cut <= bad.Length; cut++)
            {
                var f = new MessageFramer();
                var got = new System.Collections.Generic.List<byte[]>();
                bool r1 = f.Feed(new System.ReadOnlySpan<byte>(bad, 0, cut), got);
                bool r2 = f.Feed(new System.ReadOnlySpan<byte>(bad, cut, bad.Length - cut), got);
                if (cut >= 6 ? r1 : !r1) return "자른 위치 " + cut + ": 첫 Feed 반환 " + r1 + " (길이 1025 헤더가 완성되는 시점에만 false 여야 함)";
                if (r2) return "자른 위치 " + cut + ": 길이 1025 프레임을 받았는데 Feed 가 true";
                string d = Diff(got, L(Txt("OK")));
                if (d != null) return "자른 위치 " + cut + ": 위반 이전의 메시지는 전달되어야 함. " + d;
                if (f.Feed(Stream(L(Txt("A"))), got) || got.Count != 1) return "위반 뒤의 Feed 는 false 이고 메시지를 추가하지 않아야 함";
            }
            return null;
        });

        Run("random-chunking-two-connections", () =>
        {
            var rng = new System.Random(8080);
            for (int run = 0; run < 150; run++)
            {
                // 연결 두 개를 번갈아 먹인다: 인스턴스끼리 상태가 섞이면 안 된다
                var want = new[] { new System.Collections.Generic.List<byte[]>(), new System.Collections.Generic.List<byte[]>() };
                var got = new[] { new System.Collections.Generic.List<byte[]>(), new System.Collections.Generic.List<byte[]>() };
                var fr = new[] { new MessageFramer(), new MessageFramer() };
                byte[][] st = new byte[2][];
                int[] pos = new int[2];
                for (int c = 0; c < 2; c++)
                {
                    int n = rng.Next(1, 12);
                    for (int i = 0; i < n; i++)
                    {
                        int kind = rng.Next(10);
                        int len = kind == 0 ? 0 : (kind == 1 ? rng.Next(250, 1025) : rng.Next(1, 20));
                        want[c].Add(Pattern(len, rng.Next(256)));
                    }
                    st[c] = Stream(want[c]);
                }
                while (pos[0] < st[0].Length || pos[1] < st[1].Length)
                {
                    int c = rng.Next(2);
                    if (pos[c] >= st[c].Length) c = 1 - c;
                    int size = System.Math.Min(st[c].Length - pos[c], rng.Next(4) == 0 ? rng.Next(1, 600) : rng.Next(1, 9));
                    if (!fr[c].Feed(new System.ReadOnlySpan<byte>(st[c], pos[c], size), got[c])) return run + "회차: 정상 스트림인데 Feed 가 false";
                    pos[c] += size;
                }
                for (int c = 0; c < 2; c++)
                {
                    string d = Diff(got[c], want[c]);
                    if (d != null) return run + "회차 연결 " + c + ": " + d;
                }
            }
            return null;
        });
    }
}

